int addType(final String value){
    // Search for an existing type with the same value
    for (int i = 0; i < typeTable.size(); i++) {
        Symbol s = typeTable.get(i);
        if (value == null) {
            if (s.getValue() == null) {
                return i;
            }
        } else {
            if (value.equals(s.getValue())) {
                return i;
            }
        }
    }
    // Not found – create a new Symbol and add it to the table
    Symbol newSym = new Symbol(value);
    typeTable.add(newSym);
    return typeTable.size() - 1;
}

