public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength <= 0) {
        return this;
    }
    // Ensure the internal array has enough capacity
    int requiredSize = size + byteLength;
    if (array == null) {
        array = new byte[Math.max(16, requiredSize)];
    } else if (array.length < requiredSize) {
        int newCapacity = Math.max(array.length * 2, requiredSize);
        byte[] newArray = new byte[newCapacity];
        System.arraycopy(array, 0, newArray, 0, size);
        array = newArray;
    }
    // Copy the bytes or insert null bytes
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            array[size + i] = 0;
        }
    } else {
        System.arraycopy(byteArrayValue, byteOffset, array, size, byteLength);
    }
    size = requiredSize;
    return this;
}

