private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        int type = currentFrame[i];
        switch (type) {
            case 0: // TOP
                stackMapTableEntries.write((byte) 0);
                break;
            case 1: // INTEGER
                stackMapTableEntries.write((byte) 1);
                break;
            case 2: // FLOAT
                stackMapTableEntries.write((byte) 2);
                break;
            case 3: // LONG
                stackMapTableEntries.write((byte) 3);
                break;
            case 4: // DOUBLE
                stackMapTableEntries.write((byte) 4);
                break;
            case 5: // NULL
                stackMapTableEntries.write((byte) 5);
                break;
            case 6: // UNINITIALIZED_THIS
                stackMapTableEntries.write((byte) 6);
                break;
            case 7: // OBJECT
                stackMapTableEntries.write((byte) 7);
                int cpIndex = currentFrame[++i];
                stackMapTableEntries.write((cpIndex >> 8) & 0xFF);
                stackMapTableEntries.write(cpIndex & 0xFF);
                break;
            case 8: // UNINITIALIZED
                stackMapTableEntries.write((byte) 8);
                int offset = currentFrame[++i];
                stackMapTableEntries.write((offset >> 8) & 0xFF);
                stackMapTableEntries.write(offset & 0xFF);
                break;
            default:
                throw new IllegalArgumentException("Unknown type code: " + type);
        }
    }
}

