final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    int offset = 8; // skip magic(4), minor(2), major(2)
    int constantPoolCount = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset+1] & 0xFF);
    offset += 2;
    int currentIndex = 1;
    while (currentIndex < constantPoolEntryIndex) {
        int tag = classFileBuffer[offset] & 0xFF;
        offset++;
        switch (tag) {
            case 1: // CONSTANT_Utf8
                int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset+1] & 0xFF);
                offset += 2 + len;
                break;
            case 3: case 4: // Integer, Float
                offset += 4;
                break;
            case 5: case 6: // Long, Double
                offset += 8;
                currentIndex++; // these take two entries
                break;
            case 7: case 8: // Class, String
                offset += 2;
                break;
            case 9: case 10: case 11: // Fieldref, Methodref, InterfaceMethodref
                offset += 4;
                break;
            case 12: // NameAndType
                offset += 4;
                break;
            case 15: // MethodHandle
                offset += 3;
                break;
            case 16: // MethodType
                offset += 2;
                break;
            case 18: // InvokeDynamic
                offset += 4;
                break;
            default:
                throw new IllegalArgumentException("Invalid constant pool tag: " + tag);
        }
        currentIndex++;
    }
    int tag = classFileBuffer[offset] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Constant pool entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
