int addConstantNameAndType(final String name, final String descriptor) {
    // Search for an existing CONSTANT_NameAndType_info with the same name and descriptor
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantInfo ci = constantPool.get(i);
        if (ci instanceof ConstantNameAndTypeInfo) {
            ConstantNameAndTypeInfo nati = (ConstantNameAndTypeInfo) ci;
            String existingName = getUtf8String(nati.nameIndex);
            String existingDescriptor = getUtf8String(nati.descriptorIndex);
            if (name.equals(existingName) && descriptor.equals(existingDescriptor)) {
                return i; // Return the existing index
            }
        }
    }

    // Add the UTF-8 entries for the name and descriptor if they don't already exist
    int nameIndex = addConstantUtf8(name);
    int descriptorIndex = addConstantUtf8(descriptor);

    // Create the new CONSTANT_NameAndType_info and add it to the pool
    ConstantNameAndTypeInfo newNati = new ConstantNameAndTypeInfo(nameIndex, descriptorIndex);
    constantPool.add(newNati);

    // Return the index of the newly added entry
    return constantPool.size() - 1;
}

