private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list.isEmpty()) {
        return;
    }
    // Lock both lists in a consistent order to avoid deadlock
    Object firstLock, secondLock;
    if (System.identityHashCode(this) < System.identityHashCode(list)) {
        firstLock = this;
        secondLock = list;
    } else {
        firstLock = list;
        secondLock = this;
    }
    synchronized (firstLock) {
        synchronized (secondLock) {
            ListNodeImpl<E> current = list.head;
            while (current != null) {
                ListNodeImpl<E> next = current.next;
                list.removeListNode(current);
                this.addListNode(current);
                current = next;
            }
        }
    }
}

