protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }
    Set<E> remaining = new HashSet<>(tour);
    List<E> edgeList = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();
    double weight = 0.0;
    // pick an arbitrary edge to start
    E firstEdge = remaining.iterator().next();
    remaining.remove(firstEdge);
    edgeList.add(firstEdge);
    weight += graph.getEdgeWeight(firstEdge);
    V start = graph.getEdgeSource(firstEdge);
    V current = graph.getEdgeTarget(firstEdge);
    vertexList.add(start);
    vertexList.add(current);
    // traverse the remaining edges
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> it = remaining.iterator();
        while (it.hasNext()) {
            E e = it.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (graph.isDirected()) {
                if (src.equals(current)) {
                    it.remove();
                    edgeList.add(e);
                    weight += graph.getEdgeWeight(e);
                    current = tgt;
                    vertexList.add(current);
                    found = true;
                    break;
                }
            } else {
                if (src.equals(current) || tgt.equals(current)) {
                    it.remove();
                    edgeList.add(e);
                    weight += graph.getEdgeWeight(e);
                    current = src.equals(current) ? tgt : src;
                    vertexList.add(current);
                    found = true;
                    break;
