        }
    }
    // close the cycle if necessary
    if (!vertexList.get(0).equals(vertexList.get(vertexList.size() - 1))) {
        vertexList.add(vertexList.get(0));
    }
    return new org.jgrapht.graph.DefaultGraphPath<>(graph, vertexList, edgeList, weight);
}

