private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long totalSum = 0;
    int[] temp = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        totalSum += bounds.get(i);
        temp[i] = (int) totalSum;
    }
    for (int val : temp) {
        suffix.add(val);
    }
    return new Pair<>(suffix, totalSum);
}

