private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        int maxIndex = -1;
        K maxKey = null;
        for (int j = 0; j < keys.size(); j++) {
            if (i == j) continue;
            K candidate = keys.get(j);
            K current = keys.get(i);
            @SuppressWarnings("unchecked")
            int cmp = ((Comparable<K>)candidate).compareTo(current);
            if (cmp < 0) {
                if (maxKey == null || ((Comparable<K>)candidate).compareTo(maxKey) > 0) {
                    maxKey = candidate;
                    maxIndex = j;
                }
            }
        }
        lowerBounds.add(maxIndex);
    }
    return lowerBounds;
}

