        if (c == '\\' && i + 1 < input.length()) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
