                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case 'x':
                    if (i + 3 < input.length()) {
                        String hex = input.substring(i + 2, i + 4);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 3;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('x');
                        }
                    } else {
                        sb.append('\\').append('x');
                    }
                    break;
                case 'u':
                    if (i + 5 < input.length()) {
                        String hex = input.substring(i + 2, i + 6);
                        try {
