public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new ArrayList<>();
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return result;
    }
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    String[] parts = rawPath.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String segmentPart;
        String matrixPart = null;
        int semicolonIndex = part.indexOf(';');
        if (semicolonIndex >= 0) {
            segmentPart = part.substring(0, semicolonIndex);
            matrixPart = part.substring(semicolonIndex + 1);
        } else {
            segmentPart = part;
        }
        String pathValue;
        try {
            pathValue = decode ? java.net.URLDecoder.decode(segmentPart, "UTF-8") : segmentPart;
        } catch (Exception e) {
            pathValue = segmentPart;
        }
        javax.ws.rs.core.MultivaluedMap<String, String> matrixParams = new javax.ws.rs.core.MultivaluedHashMap<>();
        if (matrixPart != null && !matrixPart.isEmpty()) {
            String[] params = matrixPart.split(";");
            for (String param : params) {
                if (param.isEmpty()) {
                    continue;
                }
                int eqIndex = param.indexOf('=');
                String key;
                String value = null;
                if (eqIndex >= 0) {
                    key = param.substring(0, eqIndex);
                    value = param.substring(eqIndex + 1);
                } else {
                    key = param;
                }
                try {
                    key = java.net.URLDecoder.decode(key, "UTF-8");
                } catch (Exception e) {
                    // keep original
                }
                if (value != null) {
                    try {
                        value = java.net.URLDecoder.decode(value, "UTF-8");
                    } catch (Exception e) {
                        // keep original
                    }
                }
                matrixParams.add(key, value);
            }
        }
        result.add(new PathSegmentImpl(pathValue, matrixParams));
    }
    return result;
}

