    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        // Escape sequence
        if (i + 1 >= len) {
            // Trailing backslash, just append it
            sb.append('\\');
            break;
        }
        char next = str.charAt(i + 1);
        switch (next) {
            case 'b':
                sb.append('\b');
                i += 1;
                break;
            case 't':
                sb.append('\t');
                i += 1;
                break;
            case 'n':
                sb.append('\n');
                i += 1;
                break;
            case 'f':
                sb.append('\f');
                i += 1;
                break;
            case 'r':
                sb.append('\r');
                i += 1;
                break;
            case '\"':
                sb.append('\"');
                i += 1;
                break;
            case '\'':
                sb.append('\'');
                i += 1;
                break;
            case '\\':
                sb.append('\\');
                i += 1;
                break;
            case 'u':
                // Unicode escape: \uXXXX
                if (i + 6 > len) {
                    throw new IllegalArgumentException("Invalid Unicode escape sequence at position " + i);
                }
                String hex = str.substring(i + 2, i + 6);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid Unicode escape sequence '\\u" + hex + "' at position " + i);
                }
                i += 5; // skip \uXXXX
                break;
            default:
                if (next >= '0' && next <= '7') {
                    // Octal escape: up to 3 octal digits
                    int j = i + 1;
                    int end = j;
                    while (end < len && end - j < 3 && str.charAt(end) >= '0' && str.charAt(end) <= '7') {
                        end++;
                    }
                    String oct = str.substring(j, end);
                    try {
                        int code = Integer.parseInt(oct, 8);
                        sb.append((char) code);
