                        throw new IllegalArgumentException("Invalid octal escape sequence '\\" + oct + "' at position " + i);
                    }
                    i = end - 1; // will be incremented by loop
                } else {
                    // Unrecognized escape, keep as is
                    sb.append(next);
                    i += 1;
                }
                break;
        }
    }
    return sb.toString();
