public static String applyRelativePath(String path, String relativePath) {
    if (path == null || path.isEmpty()) {
        return relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    // Determine the base directory from the given path
    String baseDir;
    if (path.endsWith("/")) {
        baseDir = path;
    } else {
        int lastSlash = path.lastIndexOf('/');
        if (lastSlash >= 0) {
            baseDir = path.substring(0, lastSlash + 1);
        } else {
            baseDir = "";
        }
    }

    // Combine base directory with the relative path
    String combined = baseDir + relativePath;

    // Normalize the combined path
    String[] parts = combined.split("/");
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    boolean isAbsolute = combined.startsWith("/");

    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            } else {
                // If the path is absolute, ignore leading ".."
                // If relative, we simply skip it to avoid going above root
            }
        } else {
            stack.addLast(part);
        }
    }

    // Build the normalized path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }

    return result.toString();
}

