public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("index: " + index + ", len: " + len + ", length: " + str.length());
    }
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        int codePoint;
        if (Character.isHighSurrogate(ch) && i + 1 < end) {
            char low = str.charAt(i + 1);
            if (Character.isLowSurrogate(low)) {
                codePoint = Character.toCodePoint(ch, low);
                i++; // skip low surrogate
            } else {
                // Unpaired high surrogate, treat as individual char
                codePoint = ch;
            }
        } else {
            codePoint = ch;
        }

        if (codePoint <= 0x7F) {
            size += 1;
        } else if (codePoint <= 0x7FF) {
            size += 2;
        } else if (codePoint <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

